import re
from typing import Pattern

def _create_in_regex(self) -> Pattern:
    return re.compile(r'\bIN\s*\(([^()]+)\)', re.IGNORECASE)

def _create_converter(self) -> _converting._Converter:
    try:
        return _converting._Converter()
    except Exception as e:
        raise RuntimeError("Failed to create converter") from e

def convert_sql(self, sql: AnyStr, params: Union[Dict[Union[str, int], Any], Sequence[Any]]) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
    try:
        if not isinstance(sql, AnyStr):
            raise ValueError("SQL must be a string.")
        if not isinstance(params, (dict, list, tuple)):
            raise ValueError("Parameters must be a dictionary, list, or tuple.")
        converted_sql = self._converter.convert(sql)
        return converted_sql, params
    except AttributeError:
        raise RuntimeError("Converter does not have a 'convert' method.")
    except Exception as e:
        raise RuntimeError(f"An error occurred during SQL conversion: {e}")

