    parser = argparse.ArgumentParser()
    subparsers = parser.add_subparsers(dest='subparser_name')

    parser.add_argument('--global_arg', type=str, help='A global argument')

    subparser1 = subparsers.add_parser('subcommand1')
    subparser1.add_argument('--arg1', type=int, help='An argument for subcommand1')

    subparser2 = subparsers.add_parser('subcommand2')
    subparser2.add_argument('--arg2', type=str, help='An argument for subcommand2')

    try:
        args = parser.parse_args(unparsed_arguments)
    except SystemExit:
        return {}

    result = {}
    if args.subparser_name:
        result[args.subparser_name] = args
    else:
        result['global'] = args

    return result

