    parsed_dict = {}
    for arg in unparsed_arguments:
        if '=' in arg:
            key, value = arg.split('=', 1)
            parsed_dict[key.strip()] = value.strip()
        elif arg.strip():
            raise ValueError(f"Invalid argument format: {arg}")
    return parsed_dict

