def deep_merge_nodes(nodes):
    from collections.abc import Mapping

    def merge_into(target_dict, source_dict):
        for key, value in source_dict.items():
            if isinstance(value, Mapping) and key in target_dict and isinstance(target_dict[key], Mapping):
                merge_into(target_dict[key], value)
            else:
                target_dict[key] = value

    if not isinstance(nodes, list):
        raise TypeError("Input must be a list of mappings")

    merged_dict = {}
    for node in nodes:
        if not isinstance(node, Mapping):
            raise ValueError("All elements in the list must be mappings")
        merge_into(merged_dict, node)

    return merged_dict

