def check_digests_present_and_used(self, manifest_files, digests_used):
    missing_digests = set(digests_used) - set(manifest_files.keys())
    unused_digests = set(manifest_files.keys()) - set(digests_used)

    if missing_digests:
        self.error(f"Missing digests: {', '.join(missing_digests)}")
        return False

    if unused_digests:
        self.error(f"Unused digests: {', '.join(unused_digests)}")
        return False

    return True

def validate_as_prior_version(self, prior):
    if not isinstance(prior, InventoryValidator):
        return self.error("Prior is not an instance of InventoryValidator")

    if not hasattr(prior,'version') or not hasattr(self,'version'):
        return self.error("Version attribute missing in one of the inventories")

    if not hasattr(prior, 'inventory') or not hasattr(self, 'inventory'):
        return self.error("Inventory attribute missing in one of the inventories")

    if prior.version >= self.version:
        return self.error(f"Prior version {prior.version} is not less than current version {self.version}")

    if not all(item in self.inventory for item in prior.inventory):
        return self.error("Prior inventory contains items not present in the current inventory")

    return None

