def validate_version_inventories(self, version_dirs):
    try:
        root_inventory = self.get_root_inventory()
    except Exception as e:
        raise ValueError(f"Failed to load root inventory: {e}")

    differing_digests = {}

    for version in version_dirs:
        try:
            version_inventory = self.load_version_inventory(version)
        except Exception as e:
            raise ValueError(f"Failed to load inventory for version {version}: {e}")

        if not isinstance(version_inventory, dict):
            raise TypeError(f"Inventory for version {version} is not a dictionary")

        for item, digest in version_inventory.items():
            if item not in root_inventory or root_inventory[item]!= digest:
                differing_digests[item] = digest

    return differing_digests

