import os

def _group_files_by_xml_filename(source, xmls, files):
    xmls_set = {os.path.splitext(xml)[0].lower() for xml in xmls}
    grouped_files = {}

    for file in files:
        base_name = os.path.splitext(os.path.basename(file))[0].lower()
        if base_name in xmls_set:
            if base_name not in grouped_files:
                grouped_files[base_name] = []
            grouped_files[base_name].append(file)

    return {original_xml: grouped_files.get(os.path.splitext(original_xml)[0].lower(), []) for original_xml in xmls}

