def _eval_file(prefix, file_path):
    import os
    if not file_path.startswith(prefix):
        return None

    base_name = os.path.basename(file_path)
    if not base_name.startswith(prefix):
        return None

    component_id = base_name[len(prefix):]
    _, file_ext = os.path.splitext(file_path)
    file_ext_lower = file_ext.lower()

    if file_ext_lower == '.xml':
        return None

    result = {'component_id': component_id, 'file_path': file_path}
    if file_ext_lower!= '.pdf':
        result['ftype'] = file_ext_lower[1:]

    return result

