def _explore_zipfile(zip_path):
    import zipfile
    from collections import defaultdict

    grouped_files = defaultdict(list)

    try:
        with zipfile.ZipFile(zip_path, 'r') as z:
            for file_info in z.infolist():
                if file_info.filename.endswith('.xml'):
                    xml_base_name = file_info.filename.rsplit('.', 1)[0]
                    grouped_files[xml_base_name].append(file_info.filename)
    except zipfile.BadZipFile:
        raise ValueError(f"The file at {zip_path} is not a valid zip file.")
    except Exception as e:
        raise RuntimeError(f"An error occurred while processing the zip file: {e}")

    return grouped_files

