class Hookable:
    def __init__(self):
        self._registry = {}

    def on(self, hook):
        if not isinstance(hook, str):
            raise TypeError("Hook must be a string")

        def decorator(func):
            if not callable(func):
                raise TypeError("Handler must be callable")
            if hook not in self._registry:
                self._registry[hook] = []
            self._registry[hook].append(func)
            return func

        return decorator

