def update_last_applied_manifest_dict_from_resp(last_applied_manifest, observer_schema, response):
    for key, schema in observer_schema.items():
        if key not in last_applied_manifest:
            if key in response:
                last_applied_manifest[key] = response[key]
            else:
                raise KeyError(f"Observed field '{key}' not present in the Kubernetes response")

        if isinstance(schema, dict) and isinstance(last_applied_manifest.get(key), dict) and isinstance(response.get(key), dict):
            update_last_applied_manifest_dict_from_resp(last_applied_manifest[key], schema, response[key])
        elif isinstance(schema, list) and isinstance(last_applied_manifest.get(key), list) and isinstance(response.get(key), list):
            item_schema = schema[0] if schema else {}
            for i, item in enumerate(response[key]):
                if i >= len(last_applied_manifest[key]):
                    last_applied_manifest[key].append({})
                update_last_applied_manifest_list_from_resp(last_applied_manifest[key][i], item_schema, item)

def update_last_applied_manifest_list_from_resp(last_applied_manifest, observer_schema, response):
    for i, schema_item in enumerate(observer_schema):
        if i < len(response):
            response_item = response[i]
            if isinstance(schema_item, dict) and isinstance(response_item, dict):
                if i >= len(last_applied_manifest):
                    last_applied_manifest.append({})
                update_last_applied_manifest_dict_from_resp(last_applied_manifest[i], schema_item, response_item)
            elif isinstance(schema_item, list) and isinstance(response_item, list):
                if i >= len(last_applied_manifest):
                    last_applied_manifest.append([])
                update_last_applied_manifest_list_from_resp(last_applied_manifest[i], schema_item, response_item)
            else:
                if i >= len(last_applied_manifest):
                    last_applied_manifest.append(response_item)
                else:
                    last_applied_manifest[i] = response_item
        elif i >= len(last_applied_manifest):
            last_applied_manifest.append(None)

