from collections import defaultdict

def __init__(self, shape):
    self.shape = shape
    self.histogram = defaultdict(int)

def _in_bounds(self, coord):
    return all(0 <= c < s for c, s in zip(coord, self.shape))

def fill(self, coord, weight=1):
    if isinstance(coord, (list, tuple)) and isinstance(weight, (int, float)):
        if self._in_bounds(coord):
            self.histogram[tuple(coord)] += weight

def difference(d1, d2, level=-1):
    result = {}
    for key in d1:
        if key not in d2:
            result[key] = d1[key]
        elif isinstance(d1[key], dict) and isinstance(d2[key], dict) and level!= 0:
            nested_difference = difference(d1[key], d2[key], level - 1)
            if nested_difference or level == 1:
                result[key] = nested_difference
    return result

