    pass

class Histogram:
    def __init__(self, data):
        self._data = data
        self._scale = None

    @property
    def scale(self):
        return self._scale

    @scale.setter
    def scale(self, value):
        self._scale = value

    def compute_scale(self):
        self._scale = sum(self._data)

    def scale(self, other=None, recompute=False):
        if other is None:
            if recompute or self._scale is None:
                self.compute_scale()
            return self._scale
        else:
            if not isinstance(other, (int, float)):
                raise TypeError("The 'other' parameter must be a number.")
            if self._scale == 0:
                raise LenaValueError("Cannot rescale histogram with scale equal to zero.")
            factor = other / self._scale
            self._data = [x * factor for x in self._data]
            self.scale = other

