class Graph:
    def __init__(self, scale=None, fields=None, data=None):
        self._scale = scale
        self.fields = fields if fields is not None else []
        self.data = data if data is not None else []

    def scale(self, other=None):
        if other is None:
            return self._scale
        if not isinstance(other, (int, float)) or other <= 0:
            raise LenaValueError("Invalid scale value")
        if self._scale is None or self._scale == 0:
            raise LenaValueError("Graph has unknown or zero scale")

        rescale_factor = other / self._scale
        self._scale = other

        if self.fields:
            last_field = self.fields[-1]
            for point in self.data:
                if last_field in point:
                    point[last_field] *= rescale_factor
                err_field = f"{last_field}_err"
                if err_field in point:
