def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    if not isinstance(commands, (list, tuple)):
        commands = [commands]
    full_command = commands + args
    stderr_option = subprocess.DEVNULL if hide_stderr else subprocess.PIPE
    try:
        process = subprocess.Popen(full_command, cwd=cwd, env=env, stderr=stderr_option, stdout=subprocess.PIPE)
        output, _ = process.communicate()
        if verbose:
            print(output.decode('utf-8', errors='replace'))
        if process.returncode!= 0:
            raise subprocess.CalledProcessError(process.returncode, full_command, output=output)
        return process.returncode
    except subprocess.CalledProcessError as e:
        print(f"Command failed with return code {e.returncode}: {e.cmd}")
        raise
    except Exception as e:
        print(f"An error occurred: {e}")
        raise

