def normalized(self):
    try:
        hours = int(self.hours)
        minutes = int(self.minutes)
        seconds = int(self.seconds)
    except ValueError:
        raise ValueError("Time units must be convertible to integers.")

    if not (0 <= hours < 24):
        raise ValueError("Hours must be in the range 0-23.")
    if not (0 <= minutes < 60):
