from datetime import datetime, timedelta

def fromutc(self, dt):
    if dt.tzinfo is None:
        raise ValueError("Input datetime must be timezone-aware")

    dt_target = dt.astimezone(self)

    dt_fold_0 = self.localize(dt_target.replace(fold=0), is_dst=None)
    dt_fold_1 = self.localize(dt_target.replace(fold=1), is_dst=None)

    if dt_fold_0.utcoffset() == dt.utcoffset():
        fold = 0
    elif dt_fold_1.utcoffset() == dt.utcoffset():
        fold = 1
    else:
        raise ValueError("Datetime does not match any fold state")

    return dt_target.replace(fold=fold)

