def extostr(e, max_level=MAX_LEVEL, max_path_level=MAX_PATH_LEVEL):
    if max_level <= 0:
        return "Max level reached"
    try:
        exc_type, exc_value, exc_traceback = e.__class__, e, e.__traceback__
        parts = [f"{exc_type.__name__}: {exc_value}\n"]
        traceback_level = 0
        while exc_traceback is not None and traceback_level < max_path_level:
            frame = exc_traceback.tb_frame
            filename = frame.f_code.co_filename
            lineno = exc_traceback.tb_lineno
            funcname = frame.f_code.co_name
            parts.append(f"  File \"{filename}\", line {lineno}, in {funcname}\n")
            traceback_level += 1
            exc_traceback = exc_traceback.tb_next
        return ''.join(parts)
    except AttributeError:
        return f"Failed to format exception: {e}"

from typing import Any, Callable, Hashable

def cachedmethod(cache: dict[Hashable, Any], key: Callable[..., Hashable] = hash, lock: Any = None):
    def decorator(func: Callable[..., Any]) -> Callable[..., Any]:
        def wrapper(*args: Any, **kwargs: Any) -> Any:
            k = key(*args, **kwargs)
            if lock:
                with lock:
                    if k not in cache:
                        try:
                            cache[k] = func(*args, **kwargs)
                        except Exception as e:
                            raise RuntimeError(f"Error executing {func.__name__}: {e}")
                    return cache[k]
            else:
                if k not in cache:
                    try:
                        cache[k] = func(*args, **kwargs)
                    except Exception as e:
                        raise RuntimeError(f"Error executing {func.__name__}: {e}")
                return cache[k]
        return wrapper
    return decorator

