from concurrent.futures import ThreadPoolExecutor

def xargs(cmd: tuple[str,...], varargs: Sequence[str], *, color: bool = False, target_concurrency: int = 1, **kwargs) -> List[subprocess.CompletedProcess]:
    if color:
        try:
            subprocess.run(cmd + ('--color=always', '--help'), check=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
            cmd += ('--color=always',)
        except subprocess.CalledProcessError:
            pass

    def run_command(args):
        return subprocess.run(cmd + tuple(args), **kwargs, capture_output=True, text=True)

    results = []
    with ThreadPoolExecutor(max_workers=target_concurrency) as executor:
        future_to_args = {executor.submit(run_command, args): args for args in [varargs[i:i + target_concurrency] for i in range(0, len(varargs), target_concurrency)]}
        for future in future_to_args:
            try:
                result = future.result()
                results.append(result)
            except Exception as exc:
                results.append(subprocess.CompletedProcess(cmd + tuple(future_to_args[future]), returncode=-1, stdout='', stderr=str(exc)))

    return results

