def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    import os
    import shutil
    import tarfile
    import zipfile
    import gzip
    import bz2
    from pathlib import Path
    import tempfile

    tmp_path = Path(tmp_path)
    if not tmp_path.exists():
        tmp_path.mkdir(parents=True)

    try:
        if tarfile.is_tarfile(archive_path):
            with tarfile.open(archive_path, 'r') as tar:
                tar.extractall(path=tmp_path)
        elif zipfile.is_zipfile(archive_path):
            with zipfile.ZipFile(archive_path, 'r') as zip_ref:
                zip_ref.extractall(tmp_path)
        elif archive_path.endswith('.gz'):
            with gzip.open(archive_path, 'rb') as gz_file:
                with open(tmp_path / Path(archive_path).stem, 'wb') as out_file:
                    shutil.copyfileobj(gz_file, out_file)
        elif archive_path.endswith('.bz2'):
            with bz2.open(archive_path, 'rb') as bz2_file:
                with open(tmp_path / Path(archive_path).stem, 'wb') as out_file:
                    shutil.copyfileobj(bz2_file, out_file)
        else:
            raise ValueError("Unsupported archive format")

        if filename:
            extracted_files = list(tmp_path.rglob(filename))
            if extracted_files:
                return str(extracted_files[0].resolve())
            else:
                raise FileNotFoundError(f"File {filename} not found in archive")
        else:
            return str(tmp_path.resolve())
    finally:
        shutil.rmtree(tmp_path)

