import datetime

def parse_frequency(frequency):
    if frequency is None or frequency == "always":
        return None
    parts = frequency.split()
    if len(parts)!= 2:
        raise ValueError("Frequency must be in the format 'number timeunit'")
    try:
        number = int(parts[0])
    except ValueError:
        raise ValueError("The number in frequency must be an integer")
    timeunit = parts[1]
    valid_timeunits = {"seconds", "minutes", "hours", "days", "weeks"}
    if timeunit not in valid_timeunits:
        raise ValueError(f"Unsupported time unit '{timeunit}'. Valid units are: {', '.join(valid_timeunits)}")
    return datetime.timedelta(**{timeunit: number})

