def load_configurations(config_filenames, overrides=None, resolve_env=True):
    config_dict = {}
    log_records = []

    logger = logging.getLogger(__name__)

    def resolve_environment_variables(config):
        if isinstance(config, dict):
            return {k: resolve_environment_variables(v) for k, v in config.items()}
        elif isinstance(config, list):
            return [resolve_environment_variables(item) for item in config]
        elif isinstance(config, str):
            return os.path.expandvars(config)
        else:
            return config

    def merge_dicts(dict1, dict2):
        for key, value in dict2.items():
            if isinstance(value, dict) and key in dict1 and isinstance(dict1[key], dict):
                merge_dicts(dict1[key], value)
            else:
                dict1[key] = value
        return dict1

    for filename in config_filenames:
        try:
            with open(filename, 'r') as file:
                config = json.load(file)
                if resolve_env:
                    config = resolve_environment_variables(config)
                if overrides:
                    config = merge_dicts(config, overrides)
                config_dict[filename] = config
        except IOError as e:
            record = logging.LogRecord(name=logger.name, level=logging.ERROR, pathname=filename, lineno=0, msg=f"IOError: {str(e)}", args=(), exc_info=True)
            log_records.append(record)
        except json.JSONDecodeError as e:
            record = logging.LogRecord(name=logger.name, level=logging.ERROR, pathname=filename, lineno=0, msg=f"JSONDecodeError: {str(e)}", args=(), exc_info=True)
            log_records.append(record)

    return config_dict, log_records

