import yaml
import os

def get_plugin_spec_flatten_dict(plugin_dir):
    result = {}
    for root, _, files in os.walk(plugin_dir):
        for file in files:
            if file.lower().endswith(('.yaml', '.yml')):
                try:
                    with open(os.path.join(root, file), 'r') as f:
                        data = yaml.safe_load(f)
                        if isinstance(data, dict):
                            flatten(data, result, '')
                except (IOError, yaml.YAMLError):
                    pass
    return result

def flatten(d, result, parent_key):
    if not isinstance(d, dict):
        return
    for k, v in d.items():
        new_key = f"{parent_key}.{k}" if parent_key else k
        if isinstance(v, dict):
            flatten(v, result, new_key)
        else:
            result[new_key] = v

import os

def inject_config(self):
    ansible_config_path = getattr(self, 'ansible_config_path', None)
    if 'ANSIBLE_CONFIG' not in os.environ and isinstance(ansible_config_path, str):
        os.environ['ANSIBLE_CONFIG'] = ansible_config_path

import json
from xml.etree import ElementTree as ET

def identify_request(request: RequestType):
    try:
        json_data = request.get_json()
        if 'events' in json_data:
            return True
    except (TypeError, json.JSONDecodeError):
        pass

    try:
        xml_data = request.get_data(as_text=True)
        root = ET.fromstring(xml_data)
        if root.tag == 'Magic_ENV_TAG':
            return True
    except (TypeError, ET.ParseError):
        pass

    return False

from typing import Any, Dict

def identify_request(request: RequestType) -> bool:
    try:
        data: Dict[str, Any] = request.json()
        return isinstance(data, dict) and 'events' in data
    except (AttributeError, ValueError):
        return False

from datetime import datetime, timezone

def ensure_timezone(dt):
    if dt.tzinfo is None:
        return dt.replace(tzinfo=timezone.utc)
    return dt

def format_dt(dt):
    return ensure_timezone(dt).strftime('%Y-%m-%d %H:%M:%S %Z')

from typing import Set, Tuple, Callable
import re
from io import StringIO

def find_tags(text: str, replacer: Callable[[str], str] = None) -> Tuple[Set[str], str]:
    CODE_BLOCK_DELIMITER = '```'
    TAG_PATTERN = re.compile(r'#(\w+)')
    tags = set()
    code_block = False
    result = StringIO()
    index = 0

    while index < len(text):
        if text[index:index + len(CODE_BLOCK_DELIMITER)] == CODE_BLOCK_DELIMITER:
            code_block = not code_block
            result.write(text[index:index + len(CODE_BLOCK_DELIMITER)])
            index += len(CODE_BLOCK_DELIMITER)
        elif not code_block:
            match = TAG_PATTERN.match(text[index:])
            if match:
                tag = match.group(1)
                tags.add(tag)
                if replacer:
                    result.write(replacer(tag))
                else:
                    result.write(f'#{tag}')
                index += len(match.group(0))
            else:
                result.write(text[index])
                index += 1
        else:
            result.write(text[index])
            index += 1

    return tags, result.getvalue()

import re

def process_text_links(text):
    if not isinstance(text, str):
        raise ValueError("Input must be a string")

    url_pattern = r'(https?://[^\s]+)'
    def linkify(match):
        url = match.group(0)
        return f'<a href="{url}" target="_blank" rel="noopener noreferrer">{url}</a>'

    try:
        return re.sub(url_pattern, linkify, text)
    except re.error as e:
        raise RuntimeError(f"Regex error: {e}")

import requests
from requests.exceptions import RequestException

def fetch_content_type(url: str) -> str:
    headers = {'User-Agent': 'Mozilla/5.0'}
    try:
        response = requests.head(url, headers=headers, timeout=10)
        response.raise_for_status()
        return response.headers.get('Content-Type', '')
    except RequestException:
        return ''

def test_tag(tag: str) -> bool:
    LEEGAL_TAG_CHARS = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_.:"
    return all(char not in LEEGAL_TAG_CHARS for char in tag)

def xml_children_as_dict(node):
    result = {}
    for child in node:
        if child.tag in result:
            if not isinstance(result[child.tag], list):
                result[child.tag] = [result[child.tag]]
            result[child.tag].append(child.text or '')
        else:
            result[child.tag] = child.text or ''
    return result

def check_sender_and_entity_handle_match(sender_handle: str, entity_handle: str) -> bool:
    if sender_handle is None or entity_handle is None:
        return False
    return sender_handle == entity_handle

from typing import Optional
import os
import re

def get_nodeinfo_well_known_document(url: str, document_path: Optional[str] = None) -> dict:
    if not re.match(r'^https?://[^\s]+$', url):
        raise ValueError("Invalid URL format")
    if document_path and not os.path.isfile(document_path):
        raise FileNotFoundError(f"The file at {document_path} does not exist")
    return {
        "url": url,
        "document_path": document_path
    }

def verify_relayable_signature(public_key, doc, signature):
    from lxml import etree
    from Crypto.PublicKey import RSA
    from Crypto.Signature import pkcs1_15
    from Crypto.Hash import SHA256

    try:
        key = RSA.import_key(public_key)
    except ValueError:
        return False

    try:
        root = etree.fromstring(doc)
    except etree.XMLSyntaxError:
        return False

    namespace = {"ds": "http://www.w3.org/2000/09/xmldsig#"}
    signed_info = root.find(".//ds:SignedInfo", namespaces=namespace)
    if signed_info is None:
        return False

    canonicalized = etree.tostring(signed_info, method='c14n', exclusive=True, with_comments=False)
    digest = SHA256.new(canonicalized)

    try:
        pkcs1_15.verify(key, signature, digest)
        return True
    except (ValueError, TypeError):
        return False

def parse_diaspora_webfinger(document: str) -> Dict:
    import json
    HCARD_REL = 'http://microformats.org/profile/hcard'

    try:
        webfinger_data = json.loads(document)
    except json.JSONDecodeError:
        raise ValueError("Invalid JSON document")

    hcard_url = None
    for link in webfinger_data.get('links', []):
        if link.get('rel') == HCARD_REL:
            hcard_url = link.get('href')
            break

    if hcard_url is None:
        raise KeyError("hcard_url not found in webfinger document")

    return {'hcard_url': hcard_url}

import requests
from urllib.parse import quote
from typing import Optional

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    try:
        localpart, domain = handle.split('@')
    except ValueError:
        return None

    url = f"https://{quote(domain)}/.well-known/webfinger?resource=acct:{quote(handle)}"
    try:
        response = requests.get(url)
        response.raise_for_status()
        return response.text
    except requests.RequestException:
        return None

def retrieve_and_parse_diaspora_webfinger(handle):
    import requests
    from xml.etree import ElementTree as ET

    base_url = "https://diaspora.{}"
    webfinger_path = "/.well-known/webfinger?resource=acct:{}"
    url = base_url.format(handle.split('@')[1]) + webfinger_path.format(handle)

    try:
        response = requests.get(url, timeout=10)
        response.raise_for_status()
    except requests.RequestException:
        return {}

    try:
        root = ET.fromstring(response.content)
        xmlns = {'xrd': 'http://docs.oasis-open.org/ns/xri/xrd-1.0'}
        data = {}
        for link in root.findall('xrd:Link', xmlns):
            rel = link.attrib.get('rel')
            href = link.attrib.get('href')
            if rel and href:
                data[rel] = href
        return data
    except ET.ParseError:
        return {}

def retrieve_diaspora_host_meta(host):
    import requests
    try:
        from xrd import XRD
    except ImportError:
        raise ImportError("The 'xrd' library is required but not installed. Please install it using pip.")

    url = host if host.startswith(('http://', 'https://')) else f'https://{host}'
    try:
        response = requests.get(url + '/.well-known/host-meta', timeout=10)
        response.raise_for_status()
        return XRD(response.text)
    except requests.exceptions.HTTPError as e:
        raise Exception(f"HTTP error occurred: {e}")
    except requests.exceptions.ConnectionError as e:
        raise Exception(f"Connection error occurred: {e}")
    except requests.exceptions.Timeout as e:
        raise Exception(f"Timeout error occurred: {e}")
    except requests.exceptions.RequestException as e:
        raise Exception(f"Request error occurred: {e}")
    except Exception as e:
        raise Exception(f"Failed to parse XRD: {e}")

import requests
from requests.exceptions import RequestException

def send_document(url, data, timeout=10, method="post", *args, **kwargs):
    try:
        if method.lower() == "post":
            response = requests.post(url, data=data, timeout=timeout, *args, **kwargs)
        elif method.lower() == "get":
            response = requests.get(url, params=data, timeout=timeout, *args, **kwargs)
        elif method.lower() == "put":
            response = requests.put(url, data=data, timeout=timeout, *args, **kwargs)
        elif method.lower() == "delete":
            response = requests.delete(url, timeout=timeout, *args, **kwargs)
        else:
            raise ValueError(f"Unsupported method: {method}")

        response.raise_for_status()
        return response
    except RequestException as e:
        raise Exception(f"Request failed: {e}")
